"""Generate FEATURE_CATALOG.md from definitions (a test keeps the committed file in sync)."""

from __future__ import annotations

import json

from point_in_time_feature_store.definitions import FeatureRepo

__all__ = ["render_catalog"]


def _ttl(seconds: int | None) -> str:
    if seconds is None:
        return "none"
    days, rest = divmod(seconds, 86_400)
    return f"{days}d" if rest == 0 else f"{seconds}s"


def render_catalog(repo: FeatureRepo) -> str:
    lines = [
        "# Feature catalog",
        "",
        "Generated by `uv run pitfs catalog` from the definitions in",
        "`src/point_in_time_feature_store/offline/synthetic.py`. Do not edit by hand.",
        "",
        "Version hashes cover everything that determines values (entity, source, TTL, lag",
        "declaration, feature names, types and transformations); see docs/PIT_SEMANTICS.md.",
        "",
    ]
    for view in sorted(repo.feature_views, key=lambda item: item.name):
        source = repo.source(view.source)
        lines += [
            f"## {view.name}",
            "",
            f"- Version: `{view.version_hash()[:16]}`",
            f"- Entity: `{view.entity}`; source: `{source.name}` ({source.description})",
            f"- TTL: {_ttl(view.ttl_seconds)}; "
            f"zero ingestion lag: {'yes' if view.zero_ingestion_lag else 'no'}",
            f"- Owner: {view.owner}",
            f"- {view.description}" if view.description else "",
            "",
            "| Feature | Type | PII | Transformation |",
            "|---|---|---|---|",
        ]
        for name in view.feature_names:
            feature = view.feature(name)
            expression = json.dumps(
                feature.expression.model_dump(mode="json"), separators=(",", ":")
            )
            lines.append(
                f"| `{name}` | {feature.dtype.value} | {'yes' if feature.pii else 'no'} "
                f"| `{expression}` |"
            )
        lines.append("")
    return "\n".join(line for i, line in enumerate(lines) if line or (i and lines[i - 1])) + "\n"
